function esc(value) { return String(value ?? "").replace(/[&<>"']/g, (c) => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c])); }
function toast(message) { const host = $("#toastRegion"); if (!host) return; const n=document.createElement("div"); n.className="toast"; n.textContent=message; host.append(n); setTimeout(()=>n.remove(),3000); }
function setModal(sel, open) { const n=$(sel); if (n) n.setAttribute("aria-hidden", open ? "false" : "true"); }
async function api(path, options={}) { const res=await fetch(path,{...options,headers:{"Content-Type":"application/json",...(options.headers||{})}}); const data=await res.json().catch(()=>({})); if(!res.ok||data.ok===false) throw new Error(data.error||`HTTP ${res.status}`); return data; }
function storedUser(){ try{const raw=localStorage.getItem("currentUser"); const u=raw?JSON.parse(raw):null; if(u?.username&&!u.userTrackingId)u.userTrackingId=localStorage.getItem("userTrackingId")||""; return u?.username&&u?.userTrackingId?u:null;}catch{return null;} }
function setUser(user){state.user=user||null; if(!user){localStorage.removeItem("currentUser");localStorage.removeItem("username");localStorage.removeItem("userTrackingId");$("#userLabel").textContent="未接続";disconnectOnline();return;} localStorage.setItem("currentUser",JSON.stringify(user));localStorage.setItem("username",user.username||"");localStorage.setItem("userTrackingId",user.userTrackingId||"");$("#userLabel").textContent=user.username||"接続済み";}
function parseJwt(token){try{const payload=token.split(".")[1].replace(/-/g,"+").replace(/_/g,"/");return JSON.parse(decodeURIComponent(atob(payload).split("").map(c=>`%${(`00${c.charCodeAt(0).toString(16)}`).slice(-2)}`).join("")));}catch{return null;}}

async function loginCredentials(){const username=$("#loginUsername").value.trim(),password=$("#loginPassword").value;$("#authError").textContent="";if(!username||!password){$("#authError").textContent="ユーザーネームとパスワードを入力してください。";return;}try{const res=await fetch("/api/user/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username,password})});const data=await res.json();if(!res.ok||!data.exists)throw new Error(data.error||"ログインに失敗しました");setUser({email:username,username:data.username,userTrackingId:data.userTrackingId||""});setModal("#authModal",false);await bootstrap();}catch(e){$("#authError").textContent=e.message||"ログインに失敗しました。";}}
async function googleCredential(response){const p=parseJwt(response.credential);if(!p?.email)return;try{const res=await fetch("/api/user/lookup",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:p.email})});const data=await res.json();if(data.exists&&data.username){setUser({email:p.email,username:data.username,googleName:data.displayName||p.name||"",userTrackingId:data.userTrackingId||""});setModal("#authModal",false);await bootstrap();return;}state.pendingGoogle={email:p.email,gName:p.name||"ゲスト"};$("#googleUsernameInput").value=p.name||"";setModal("#authModal",false);setModal("#usernameModal",true);}catch{$("#authError").textContent="Googleログインの確認に失敗しました。";}}
async function saveGoogleUsername(){const username=$("#googleUsernameInput").value.trim(),p=state.pendingGoogle;if(!p||!username)return;try{const res=await fetch("/api/user/register",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:p.email,username,googleDisplayName:p.gName})});const data=await res.json();if(!res.ok||data.error)throw new Error(data.error||"登録に失敗しました");setUser({email:p.email,username:data.username,googleName:data.displayName||p.gName,userTrackingId:data.userTrackingId||""});state.pendingGoogle=null;setModal("#usernameModal",false);await bootstrap();}catch(e){$("#usernameError").textContent=e.message;}}
function initGoogle(){if(!window.google?.accounts?.id||!$("#googleSignInBtn"))return;google.accounts.id.initialize({client_id:GOOGLE_CLIENT_ID,callback:googleCredential,ux_mode:"popup"});google.accounts.id.renderButton($("#googleSignInBtn"),{theme:"filled_black",size:"large",shape:"pill",text:"continue_with",width:320});}

async function bootstrap(){if(!state.user?.userTrackingId)return;const id=encodeURIComponent(state.user.userTrackingId);try{const [p,pr,m]=await Promise.all([api(`/api/now-coding/profile?userTrackingId=${id}`),api(`/api/now-coding/programs?userTrackingId=${id}`),api(`/api/now-coding/matches?userTrackingId=${id}&limit=20`)]);state.profile=p.profile||{tutorialStep:0,tutorialDone:false,prefs:{}};state.programs=pr.programs||[];state.matches=m.matches||[];if(!state.selectedProgramId&&state.programs[0])state.selectedProgramId=state.programs[0].programId;renderHome();renderProgramChoices();applyTutorialGate();connectOnline();if(!state.profile.tutorialDone)requestAnimationFrame(startTutorial);}catch(e){console.error(e);toast("保存データの読み込みに失敗しました");}}
function isTutorial(){return Boolean(state.profile&&!state.profile.tutorialDone);}
async function tutorialProgress(step,done=false){if(!state.user)return;try{const d=await api("/api/now-coding/profile",{method:"PUT",body:JSON.stringify({userTrackingId:state.user.userTrackingId,tutorialStep:Math.max(Number(state.profile?.tutorialStep||0),step),tutorialDone:Boolean(done),prefs:state.profile?.prefs||{}})});state.profile=d.profile;applyTutorialGate();renderTutorial();}catch(e){console.warn(e);}}
