function newDraft(){state.draft={programId:"",name:"新しい駒",blocks:[]};renderWorkspace();}
function openProgram(id){const p=state.programs.find(x=>x.programId===id);if(!p)return;state.draft={programId:p.programId,name:p.name,blocks:deepClone(p.blocks||[])};state.selectedProgramId=p.programId;showView("editor",true);}
const lit=(value)=>({type:"literal",value});
const builtin=(name)=>({type:"builtin",name});
const sensor=(direction)=>({type:"sensor",direction});
const binary=(op,left,right)=>({type:"binary",op,left,right});
function defaultCondition(){return binary("==",sensor("front"),lit("cliff"));}
function createBlock(type){
 if(type==="move")return{type:"action",action:"move"};
 if(type==="turn")return{type:"action",action:"turnRight",uiKind:"turn"};
 if(type==="attack")return{type:"action",action:"attack",uiKind:"attack",range:lit(3)};
 if(type==="if")return{type:"if",condition:defaultCondition(),then:[],else:[]};
 if(type==="forever")return{type:"forever",body:[]};
 if(type==="while")return{type:"while",condition:binary("!=",builtin("enemyDistance"),lit(2)),body:[]};
 if(type==="repeat")return{type:"repeat",times:lit(3),body:[]};
 if(type==="break")return{type:"break"};
 if(type==="setVar")return{type:"set",name:"value",value:lit(0)};
 if(type==="changeVar")return{type:"change",name:"value",value:lit(1)};
 return{type:"action",action:"move"};
}

function seqByPath(path){let seq=state.draft.blocks;for(const part of path){const block=seq[part.index];if(!block)return null;seq=block[part.branch];if(!Array.isArray(seq))return null;}return seq;}
function pathKey(path){return path.map(p=>`${p.index}:${p.branch}`).join("/")||"root";}
function exprSummary(expr){if(!expr)return"0";if(expr.type==="literal")return String(expr.value);if(expr.type==="var")return `変数 ${expr.name||"value"}`;if(expr.type==="builtin")return({enemyDistance:"敵との距離",ink:"インク",tailLength:"尾の長さ",noMoveTicks:"停止tick"})[expr.name]||expr.name;if(expr.type==="sensor")return DIR_LABELS[expr.direction]||"前";if(expr.type==="random")return `乱数 ${exprSummary(expr.min)}〜${exprSummary(expr.max)}`;if(expr.type==="not")return `${exprSummary(expr.value)} ではない`;if(expr.type==="binary")return `${exprSummary(expr.left)} ${COMPARE[expr.op]||MATH[expr.op]||({and:"かつ",or:"または"})[expr.op]||expr.op} ${exprSummary(expr.right)}`;return"値";}
function exprKind(expr){if(!expr)return"number";if(expr.type==="sensor")return"cell";if(expr.type==="binary"&&["==","!=","<","<=",">",">=","and","or"].includes(expr.op))return"boolean";if(expr.type==="not")return"boolean";return"number";}
